func (c *CLab) deployWithLabRuntime(
	ctx context.Context,
	options *DeployOptions,
) ([]clabruntime.GenericContainer, error) {
	if len(c.nodeFilter) != 0 {
		return nil, fmt.Errorf("node-filter is not supported for lab runtime %q",
			c.globalRuntimeName)
	}

	if len(c.renderedTopology) == 0 {
		return nil, fmt.Errorf("rendered topology is empty")
	}

	if options != nil && options.reconfigure {
		// --reconfigure regenerates the lab from scratch, like removing a local lab
		// directory, so it also deletes the persistent node storage.
		err := c.LabRuntime.Destroy(ctx, clablabruntime.DestroyRequest{
			Identity:   c.labRuntimeIdentity,
			Name:       c.Config.Name,
			Wait:       true,
			Timeout:    c.timeout,
			MaxWorkers: options.maxWorkers,
			Cleanup:    true,
		})
		if err != nil {
			return nil, err
		}
	}

	req, err := c.labRuntimeDeployRequest()
	if err != nil {
		return nil, err
	}
	req.Wait = true
	applyLabRuntimeDeployOptions(&req, options)

	state, err := c.LabRuntime.Deploy(ctx, req)
	if err != nil {
		return nil, err
	}

	return c.containersFromLabState(state), nil
}

func (c *CLab) labRuntimeDeployRequest() (clablabruntime.DeployRequest, error) {
	if c.Config.Name == "" {
		return clablabruntime.DeployRequest{}, fmt.Errorf("topology name is required")
	}
	if len(c.renderedTopology) == 0 {
		return clablabruntime.DeployRequest{}, fmt.Errorf("rendered topology is empty")
	}

	topologyFile := ""
	topologyLabDir := ""
	if c.TopoPaths != nil {
		topologyFile = c.TopoPaths.TopologyFilenameAbsPath()
		topologyLabDir = c.TopoPaths.TopologyLabDir()
	}

	return clablabruntime.DeployRequest{
		Identity:           c.labRuntimeIdentity,
		Name:               c.Config.Name,
		Owner:              c.labOwner(),
		TopologyFile:       topologyFile,
		TopologyLabDir:     topologyLabDir,
		TopologyDefinition: c.renderedTopology,
		Timeout:            c.timeout,
	}, nil
}

// applyLabRuntimeDeployOptions copies the deploy options that shape remote resources onto the
// runtime request in one place, so every path that builds a request agrees on them.
func applyLabRuntimeDeployOptions(req *clablabruntime.DeployRequest, options *DeployOptions) {
	if options == nil {
		return
	}

	req.NoTopologyCR = options.noTopologyCR
	req.ImagePullSecret = options.imagePullSecret
	req.ExposeType = options.exposeType
	req.NoPersistence = options.noPersistence
	req.MaxWorkers = options.maxWorkers
}

// LabRuntimeManifests renders the remote resources the selected runtime would create for the
// topology, shaped by the same deploy options a real deployment honors, without contacting the
// runtime's backend.
func (c *CLab) LabRuntimeManifests(
	ctx context.Context,
	options *DeployOptions,
) ([]clablabruntime.Manifest, error) {
	if c.LabRuntime == nil {
		return nil, fmt.Errorf("no lab runtime selected")
	}

	emitter, ok := c.LabRuntime.(clablabruntime.ManifestEmitter)
	if !ok {
		return nil, fmt.Errorf(
			"lab runtime %q does not support emitting manifests",
			c.globalRuntimeName,
		)
	}

	req, err := c.labRuntimeDeployRequest()
	if err != nil {
		return nil, err
	}
	applyLabRuntimeDeployOptions(&req, options)

	return emitter.Manifests(ctx, req)
}

// ValidateLabRuntimeTopology executes the selected runtime's compiler without mutation.
func (c *CLab) ValidateLabRuntimeTopology(ctx context.Context) error {
	if c.LabRuntime == nil {
		return fmt.Errorf("no lab runtime selected")
	}

	validator, ok := c.LabRuntime.(clablabruntime.TopologyValidator)
	if !ok {
		return fmt.Errorf(
			"lab runtime %q does not support topology validation",
			c.globalRuntimeName,
		)
	}

	req, err := c.labRuntimeDeployRequest()
	if err != nil {
		return err
	}

	return validator.Validate(ctx, req)
}

func (c *CLab) destroyWithLabRuntime(ctx context.Context, opts *DestroyOptions) error {
	if len(opts.nodeFilter) != 0 {
		return fmt.Errorf(
			"node-filter is not supported for lab runtime %q; no resources were deleted",
			c.globalRuntimeName,
		)
	}

	if opts.all {
		return c.destroyAllWithLabRuntime(ctx, opts)
	}

	if c.Config.Name == "" {
		return fmt.Errorf("topology name is required")
	}

	err := c.LabRuntime.Destroy(ctx, clablabruntime.DestroyRequest{
		Identity:   c.labRuntimeIdentity,
		Name:       c.Config.Name,
		Wait:       true,
		Timeout:    c.timeout,
		MaxWorkers: opts.maxWorkers,
		Cleanup:    opts.cleanup,
	})
	if err != nil {
		return err
	}

	if opts.cleanup {
		return c.cleanupLabRuntimeLabDir()
	}

	return nil
}

