	nodeDefinition := t.Nodes[nodeName]
	if nodeDefinition != nil && nodeDefinition.Stages != nil {
		s.Merge(nodeDefinition.Stages)
	}

	// set nil values to their respective defaults
	s.InitDefaults()

	return s, nil
}

